package site.kael.conversationcompiler.manager.settings;
import org.springframework.stereotype.Component; import site.kael.conversationcompiler.common.BadRequestException; import site.kael.conversationcompiler.domain.settings.*; import site.kael.conversationcompiler.repository.settings.*; import java.util.*;
@Component public class KnowledgeSettingsManager { private final KnowledgeSettingsRepository settings; private final ModelProviderRepository providers; public KnowledgeSettingsManager(KnowledgeSettingsRepository s,ModelProviderRepository p){settings=s;providers=p;} public Optional<KnowledgeCompileSettings> get(){return settings.find();} public void save(KnowledgeSettingsRequest r){if(r.intervalMinutes()==null||r.intervalMinutes()<1)throw new BadRequestException("intervalMinutes must be a positive integer");if(r.providerId()==null||!providers.exists(r.providerId()))throw new BadRequestException("provider not found");var p=providers.findById(r.providerId()).orElseThrow();if(!p.enabled())throw new BadRequestException("provider is disabled");if(r.modelName()==null||!providers.findModels(r.providerId()).contains(r.modelName()))throw new BadRequestException("model is not available for provider");settings.save(r.providerId(),r.modelName(),r.intervalMinutes(),r.prompt()==null?"":r.prompt(),r.enabled()==null||r.enabled());} public List<ModelOptions> options(){return providers.findAll().stream().filter(ModelProvider::enabled).map(p->new ModelOptions(p.id(),p.name(),p.interfaceType(),p.models())).toList();}}
